def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    opp_requirements = []
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev['bid'])

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.25))

    total_agents = 1 + len(alive_opponents)
    total_req = WATER_REQ + sum(opp_requirements)
    slack = supply - total_req
    per_agent_supply = supply / float(total_agents)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1
    tight_supply = slack <= 0 or per_agent_supply < WATER_REQ
    loose_supply = slack >= WATER_REQ

    if urgent:
        target = max(78.0, highest_prev + 2.0)
    elif tight_supply:
        target = max(74.0, highest_prev + 1.25)
    elif pressured:
        target = max(72.0, avg_prev + 1.0)
    elif loose_supply:
        target = max(38.0, avg_prev * 0.72)
    else:
        target = max(52.0, avg_prev * 0.82)

    if highest_prev >= 80 and not urgent and hp >= 5:
        target = min(target, 58.0)

    if supply >= 23 and hp >= 5 and no_water_days == 0:
        target = min(target, 50.0)

    if budget < DAILY_SALARY * 1.2:
        if urgent:
            target = max(target, budget * 0.9)
        else:
            target = min(target, budget * 0.55)

    target = min(target, budget)
    if target < 0:
        target = 0.0
    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.5 
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)
        if highest_prev_bid > DAILY_SALARY * 0.55:
            base_bid = highest_prev_bid + 2 
        else:
            base_bid = max(base_bid, average_prev_bid + 1)

    base_bid = max(base_bid, DAILY_SALARY * 0.45)

    current_bid = base_bid

    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
        current_bid = min(my_status['budget'], DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 6:
        current_bid = min(my_status['budget'], max(current_bid, DAILY_SALARY * 0.75))

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['budget'] > DAILY_SALARY * 2:
        current_bid = min(my_status['budget'], max(current_bid, DAILY_SALARY * 0.8))

    num_possible_winners = int(day_context['supply'] // WATER_REQ)
    num_active_opponents = len(alive_opponents)

    if num_possible_winners < (num_active_opponents + 1) / 2:
        if my_status['hp'] > 6 and my_status['no_water_days'] == 0:
             current_bid = min(my_status['budget'], max(current_bid, base_bid * 1.1))

    final_bid = min(my_status['budget'], current_bid)

    return max(0.0, final_bid)
